
DO $finance_reconcile$
DECLARE e jsonb; old record; candidate record; idx regclass; wanted text; normalized text;
BEGIN
 IF to_regclass('student_subscription_payments') IS NULL OR to_regclass('student_subscription_allocations') IS NULL THEN
  RAISE EXCEPTION 'Finance tables must both exist for reconciliation';
 END IF;
 IF EXISTS(SELECT FROM pg_constraint WHERE conrelid='student_subscription_payments'::regclass
   AND conname='student_subscription_payments_money_ck') THEN
  ALTER TABLE student_subscription_payments RENAME CONSTRAINT student_subscription_payments_money_ck TO student_subscription_payments_gross_ck;
 END IF;
 FOR e IN SELECT value FROM jsonb_array_elements('[{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_amount_ck","type":"c","definition":"CHECK (((amount_minor > 0) AND (currency = ''NGN''::text) AND (((entry_type = ''CREDIT''::text) AND (recipient_type = ANY (ARRAY[''SCHOOL''::text, ''PLATFORM''::text, ''PARTNER''::text]))) OR ((entry_type = ''REVERSAL''::text) AND (recipient_type = ANY (ARRAY[''SCHOOL''::text, ''PLATFORM''::text, ''PARTNER''::text]))) OR ((entry_type = ''EXPENSE''::text) AND (recipient_type = ''PLATFORM_PROVIDER_FEE''::text)))))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_attribution_id_fkey","type":"f","definition":"FOREIGN KEY (attribution_id) REFERENCES school_partner_attributions(id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_attribution_partner_fk","type":"f","definition":"FOREIGN KEY (attribution_id, recipient_id) REFERENCES school_partner_attributions(id, partner_profile_id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_commission_rule_id_fkey","type":"f","definition":"FOREIGN KEY (commission_rule_id) REFERENCES commission_rules(id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_entry_ck","type":"c","definition":"CHECK ((entry_type = ANY (ARRAY[''CREDIT''::text, ''REVERSAL''::text, ''EXPENSE''::text])))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_id_payment_entry_recipient_uq","type":"u","definition":"UNIQUE (id, payment_id, entry_type, recipient_type)","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_partner_ck","type":"c","definition":"CHECK ((((recipient_type = ''PARTNER''::text) AND (recipient_id IS NOT NULL) AND (attribution_id IS NOT NULL) AND (commission_rule_id IS NOT NULL)) OR ((recipient_type <> ''PARTNER''::text) AND (recipient_id IS NULL))))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_payer_user_id_fkey","type":"f","definition":"FOREIGN KEY (payer_user_id) REFERENCES app_users(id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_payment_owner_term_fk","type":"f","definition":"FOREIGN KEY (payment_id, subscription_id, school_id, student_id, academic_session_id, academic_term_id) REFERENCES student_subscription_payments(id, subscription_id, school_id, student_id, academic_session_id, academic_term_id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_pkey","type":"p","definition":"PRIMARY KEY (id)","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_recipient_ck","type":"c","definition":"CHECK ((recipient_type = ANY (ARRAY[''SCHOOL''::text, ''PLATFORM''::text, ''PARTNER''::text, ''PLATFORM_PROVIDER_FEE''::text])))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_school_id_fkey","type":"f","definition":"FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_session_school_fk","type":"f","definition":"FOREIGN KEY (academic_session_id, school_id) REFERENCES academic_sessions(id, school_id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_student_id_fkey","type":"f","definition":"FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_student_school_fk","type":"f","definition":"FOREIGN KEY (student_id, school_id) REFERENCES students(id, school_id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_allocations","name":"student_subscription_allocations_term_school_fk","type":"f","definition":"FOREIGN KEY (academic_term_id, school_id) REFERENCES academic_terms(id, school_id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_gross_ck","type":"c","definition":"CHECK (((gross_amount_minor = 500000) AND (currency = ''NGN''::text) AND ((provider_fee_minor IS NULL) OR (provider_fee_minor >= 0)) AND ((settlement_amount_minor IS NULL) OR ((settlement_amount_minor >= 0) AND (settlement_amount_minor <= gross_amount_minor)))))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_id_owner_term_uq","type":"u","definition":"UNIQUE (id, subscription_id, school_id, student_id, academic_session_id, academic_term_id)","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_payer_user_id_fkey","type":"f","definition":"FOREIGN KEY (payer_user_id) REFERENCES app_users(id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_pkey","type":"p","definition":"PRIMARY KEY (id)","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_provider_ck","type":"c","definition":"CHECK ((provider = ''FLUTTERWAVE''::text))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_provider_mode_ck","type":"c","definition":"CHECK ((provider_mode = ''SANDBOX''::text))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_reconciliation_ck","type":"c","definition":"CHECK ((reconciliation_status = ANY (ARRAY[''PENDING''::text, ''RECONCILED''::text, ''RECONCILIATION_REQUIRED''::text, ''NOT_APPLICABLE''::text])))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_reference_ck","type":"c","definition":"CHECK ((reference ~ ''^[A-Za-z0-9_-]{8,100}$''::text))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_session_school_fk","type":"f","definition":"FOREIGN KEY (academic_session_id, school_id) REFERENCES academic_sessions(id, school_id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_settlement_ck","type":"c","definition":"CHECK ((settlement_status = ANY (ARRAY[''PENDING''::text, ''RECONCILED''::text, ''RECONCILIATION_REQUIRED''::text, ''NOT_APPLICABLE''::text])))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_status_ck","type":"c","definition":"CHECK ((status = ANY (ARRAY[''PENDING''::text, ''PAID''::text, ''FAILED''::text, ''RECONCILIATION_REQUIRED''::text])))","confdeltype":" ","confupdtype":" ","confmatchtype":" ","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_subscription_owner_fk","type":"f","definition":"FOREIGN KEY (subscription_id, school_id, student_id) REFERENCES subscriptions(id, school_id, student_id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true},{"table_name":"student_subscription_payments","name":"student_subscription_payments_term_school_fk","type":"f","definition":"FOREIGN KEY (academic_term_id, school_id) REFERENCES academic_terms(id, school_id) ON DELETE RESTRICT","confdeltype":"r","confupdtype":"a","confmatchtype":"s","condeferrable":false,"condeferred":false,"convalidated":true}]'::jsonb) LOOP
  wanted=e->>'definition';
  SELECT c.*,pg_get_constraintdef(c.oid) def INTO old FROM pg_constraint c
   WHERE c.conrelid=(e->>'table_name')::regclass AND c.conname=e->>'name';
  IF FOUND THEN
   IF old.def<>wanted THEN
    IF e->>'type'='f' AND replace(old.def,' ON DELETE RESTRICT','')=replace(wanted,' ON DELETE RESTRICT','') THEN
     EXECUTE format('ALTER TABLE %I DROP CONSTRAINT %I',e->>'table_name',e->>'name');
     EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I %s',e->>'table_name',e->>'name',wanted);
    ELSE RAISE EXCEPTION 'Unexpected constraint mismatch: %',e->>'name'; END IF;
   END IF;
  ELSE
   SELECT c.*,pg_get_constraintdef(c.oid) def INTO candidate FROM pg_constraint c
    WHERE c.conrelid=(e->>'table_name')::regclass AND c.contype::text=e->>'type'
    AND replace(pg_get_constraintdef(c.oid),' ON DELETE RESTRICT','')=replace(wanted,' ON DELETE RESTRICT','')
    ORDER BY c.oid LIMIT 1;
   IF FOUND THEN
    EXECUTE format('ALTER TABLE %I RENAME CONSTRAINT %I TO %I',e->>'table_name',candidate.conname,e->>'name');
    IF candidate.def<>wanted THEN
     EXECUTE format('ALTER TABLE %I DROP CONSTRAINT %I',e->>'table_name',e->>'name');
     EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I %s',e->>'table_name',e->>'name',wanted);
    END IF;
   ELSIF e->>'type'='u' AND to_regclass(e->>'name') IS NOT NULL THEN
    EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I UNIQUE USING INDEX %I',e->>'table_name',e->>'name',e->>'name');
   ELSE EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I %s',e->>'table_name',e->>'name',wanted);
   END IF;
  END IF;
 END LOOP;
END $finance_reconcile$;
CREATE OR REPLACE FUNCTION public.protect_student_subscription_allocations()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'Student subscription allocations are immutable';
END;
$function$
;
CREATE OR REPLACE FUNCTION public.protect_student_subscription_receipt_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.receipt_snapshot IS NOT NULL
     AND NEW.receipt_snapshot IS DISTINCT FROM OLD.receipt_snapshot THEN
    RAISE EXCEPTION 'Student subscription receipt snapshots are immutable';
  END IF;
  RETURN NEW;
END;
$function$
;
DO $finance_triggers$ BEGIN IF NOT EXISTS(SELECT FROM pg_trigger WHERE tgname='student_subscription_allocations_immutable'
 AND tgrelid='student_subscription_allocations'::regclass AND NOT tgisinternal) THEN EXECUTE 'CREATE TRIGGER student_subscription_allocations_immutable BEFORE DELETE OR UPDATE ON public.student_subscription_allocations FOR EACH ROW EXECUTE FUNCTION protect_student_subscription_allocations()'; END IF;
IF NOT EXISTS(SELECT FROM pg_trigger WHERE tgname='student_subscription_payment_receipt_immutable'
 AND tgrelid='student_subscription_payments'::regclass AND NOT tgisinternal) THEN EXECUTE 'CREATE TRIGGER student_subscription_payment_receipt_immutable BEFORE UPDATE ON public.student_subscription_payments FOR EACH ROW EXECUTE FUNCTION protect_student_subscription_receipt_snapshot()'; END IF; END $finance_triggers$;
